#include <Arduino.h>
void clockTask(void*) { TickType_t last = xTaskGetTickCount(); const TickType_t period = pdMS_TO_TICKS(500); for (;;) { Serial.println("500 ms"); vTaskDelayUntil(&last, period); } }
void setup() { Serial.begin(115200); if (xTaskCreate(clockTask, "clock", 2048, nullptr, 1, nullptr) != pdPASS) Serial.println("clock task creation failed"); }
void loop() { vTaskDelay(pdMS_TO_TICKS(1000)); }

#include <Arduino.h>
void periodicTask(void*) { TickType_t last = xTaskGetTickCount(); const TickType_t period = pdMS_TO_TICKS(500); for (;;) { Serial.println("periodic"); vTaskDelayUntil(&last, period); } }
void setup() { Serial.begin(115200); xTaskCreate(periodicTask, "periodic", 2048, nullptr, 1, nullptr); }
void loop() { vTaskDelay(pdMS_TO_TICKS(1000)); }
